import "errors"

var (
    errNegativeRoll   = errors.New("Negative roll is invalid")
    errPinCount       = errors.New("Pin count exceeds pins on the lane")
    errGameOver       = errors.New("Cannot roll after game is over")
    errNotGameOver    = errors.New("Score cannot be taken until the end of the game")
)

type Game struct {
    rolls       []int
    frame       int // current frame, 1-indexed
    rollInFrame int // 0 = first roll, 1 = second roll, 2 = third roll (frame 10 only)
}

func NewGame() *Game {
    return &Game{frame: 1, rollInFrame: 0}
}

func (g *Game) Roll(pins int) error {
    if pins < 0 {
        return errNegativeRoll
    }
    if pins > 10 {
        return errPinCount
    }
    if g.gameOver() {
        return errGameOver
    }
    // Validate against pins remaining in the current frame.
    if err := g.validateRoll(pins); err != nil {
        return err
    }
    g.rolls = append(g.rolls, pins)
    g.advance()
    return nil
}
```

