func (g *Game) validateRoll(pins int) error {
    n := len(g.rolls)
    if g.frame < 10 {
        if g.rollInFrame == 1 {
            first := g.rolls[n-1]
            if pins > 10-first {
                return errPinCount
            }
        }
        return nil
    }
    // frame 10
    switch g.rollInFrame {
    case 0:
        return nil
    case 1:
        roll1 := g.rolls[n-1]
        if roll1 < 10 {
            if pins > 10-roll1 {
                return errPinCount
            }
        }
        return nil
    case 2:
        roll2 := g.rolls[n-1]
        if roll2 < 10 {
            if pins > 10-roll2 {
                return errPinCount
            }
        }
        return nil
    }
    return nil
}
```

