func (g *Game) totalScore() int {
    total := 0
    i := 0
    for frame := 1; frame <= 10; frame++ {
        if frame < 10 {
            if g.rolls[i] == 10 {
                // strike
                total += 10 + g.rolls[i+1] + g.rolls[i+2]
                i++
            } else if g.rolls[i]+g.rolls[i+1] == 10 {
                // spare
                total += 10 + g.rolls[i+2]
                i += 2
            } else {
                // open
                total += g.rolls[i] + g.rolls[i+1]
                i += 2
            }
        } else {
            // frame 10: sum remaining rolls
            for ; i < len(g.rolls); i++ {
                total += g.rolls[i]
            }
        }
    }
    return total
}
```

